SELECT
  SUM(("invoice_lines".quantity * "invoice_lines".unit_price - "invoice_lines".discount_amount)) AS "metric_1"
FROM "billing"."invoice_lines" AS "invoice_lines";

SELECT
  SUM(CASE WHEN "invoice_lines".is_recurring = 1 THEN ("invoice_lines".quantity * "invoice_lines".unit_price - "invoice_lines".discount_amount) ELSE 0 END) AS "metric_1"
FROM "billing"."invoice_lines" AS "invoice_lines";

SELECT
  COUNT(DISTINCT "invoice_lines".invoice_id) AS "metric_1"
FROM "billing"."invoice_lines" AS "invoice_lines";

SELECT
  SUM(("invoice_lines".quantity * "invoice_lines".unit_price - "invoice_lines".discount_amount)) / NULLIF(COUNT(DISTINCT "invoice_lines".invoice_id), 0) AS "metric_1"
FROM "billing"."invoice_lines" AS "invoice_lines";

SELECT
  SUM("invoice_lines".discount_amount) AS "metric_1"
FROM "billing"."invoice_lines" AS "invoice_lines";

SELECT
  SUM("invoice_lines".tax_amount) AS "metric_1"
FROM "billing"."invoice_lines" AS "invoice_lines";

SELECT
  SUM(("invoice_lines".quantity * "invoice_lines".unit_price - "invoice_lines".discount_amount)) + SUM("invoice_lines".discount_amount) AS "metric_1"
FROM "billing"."invoice_lines" AS "invoice_lines";

SELECT
  SUM(CASE WHEN "invoice_lines".is_recurring = 1 THEN ("invoice_lines".quantity * "invoice_lines".unit_price - "invoice_lines".discount_amount) ELSE 0 END) / NULLIF(SUM(("invoice_lines".quantity * "invoice_lines".unit_price - "invoice_lines".discount_amount)), 0) AS "metric_1"
FROM "billing"."invoice_lines" AS "invoice_lines";
